from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n <= k:
            return [0] * n

        children = [[0] * 26]
        count = [0]
        depth = [0]

        for word in words:
            node = 0
            count[node] += 1
            for ch in word:
                idx = ord(ch) - ord('a')
                if children[node][idx] == 0:
                    children[node][idx] = len(children)
                    children.append([0] * 26)
                    count.append(0)
                    depth.append(depth[node] + 1)
                node = children[node][idx]
                count[node] += 1

        always_valid = 0
        fragile_by_depth = [0] * (max(map(len, words)) + 1)
        max_fragile_depth = 0

        for node in range(1, len(count)):
            if count[node] >= k + 1:
                always_valid = max(always_valid, depth[node])
            elif count[node] == k:
                fragile_by_depth[depth[node]] += 1
                max_fragile_depth = max(max_fragile_depth, depth[node])

        ans = []
        for word in words:
            node = 0
            removed_depths = []

            for ch in word:
                node = children[node][ord(ch) - ord('a')]
                if count[node] == k:
                    d = depth[node]
                    fragile_by_depth[d] -= 1
                    removed_depths.append(d)

            best_fragile = max_fragile_depth
            while best_fragile > 0 and fragile_by_depth[best_fragile] == 0:
                best_fragile -= 1

            ans.append(max(always_valid, best_fragile))

            for d in removed_depths:
                fragile_by_depth[d] += 1

        return ans
